type NodeCallback<T> = (err: NodeJS.ErrnoException | null, data?: T) => void;

export function readConfig(path: string, cb: NodeCallback<Config>): void {
  fs.readFile(path, 'utf8', (err, text) => {
    if (err) return cb(err);
    try { cb(null, JSON.parse(text)); }               // exactly one terminal call
    catch (e) { cb(e as NodeJS.ErrnoException); }     // error path
  });
}

export const readConfigAsync = util.promisify(readConfig);   // callback API -> promise
